function Icon({ name, size = 18, stroke = "currentColor", fill = "none" }: {
  name: IconName; size?: number; stroke?: string; fill?: string;
}) {
  const common = {
    width: size, height: size, viewBox: "0 0 24 24", fill,
    stroke, strokeWidth: 1.7, strokeLinecap: "round" as const, strokeLinejoin: "round" as const,
    "aria-hidden": true,
  };
  switch (name) {
    case "dashboard": return <svg {...common}><rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/></svg>;
    case "bell": return <svg {...common}><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg>;
    case "search": return <svg {...common}><circle cx="10.8" cy="10.8" r="6.7"/><path d="m16 16 4.2 4.2"/></svg>;
    case "chart": return <svg {...common}><path d="M4 19V5"/><path d="M4 19h16"/><path d="m7 15 4-4 3 2 6-7"/></svg>;
    case "edit": return <svg {...common}><path d="M4 20h4L19 9l-4-4L4 15v5Z"/><path d="m13.5 6.5 4 4"/></svg>;
    case "gear": return <svg {...common}><path d="m12 3 1.2 2.1 2.4.5 1.9-1.2 2.1 2.1-1.2 1.9.5 2.4L21 12l-2.1 1.2-.5 2.4 1.2 1.9-2.1 2.1-1.9-1.2-2.4.5L12 21l-1.2-2.1-2.4-.5-1.9 1.2-2.1-2.1 1.2-1.9-.5-2.4L3 12l2.1-1.2.5-2.4-1.2-1.9 2.1-2.1 1.9 1.2 2.4-.5L12 3Z"/><circle cx="12" cy="12" r="3"/></svg>;
    case "backlinks": return <svg {...common}><path d="M10 13.5a4 4 0 0 0 5.8.1l2.1-2.1a4 4 0 0 0-5.7-5.7L11 7"/><path d="M14 10.5a4 4 0 0 0-5.8-.1l-2.1 2.1a4 4 0 0 0 5.7 5.7L13 17"/></svg>;
    case "users": return <svg {...common}><circle cx="9" cy="8" r="3"/><path d="M3.5 19c.7-3.2 2.5-4.8 5.5-4.8s4.8 1.6 5.5 4.8"/><path d="M16 5.5a3 3 0 0 1 0 5.8M17 14.5c2 .6 3.2 2 3.6 4.5"/></svg>;
    case "report": return <svg {...common}><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h4M9 13h6M9 17h6"/></svg>;
    case "tasks": return <svg {...common}><path d="M5 4h14v16H5z"/><path d="m8 9 1.5 1.5L12 8M8 14l1.5 1.5L12 13M14 10h2M14 15h2"/></svg>;
    case "calendar": return <svg {...common}><rect x="3.5" y="5" width="17" height="15" rx="2"/><path d="M7 3v4M17 3v4M3.5 9h17M8 13h3M13 13h3M8 17h3"/></svg>;
    case "download": return <svg {...common}><path d="M12 3v12"/><path d="m7 10 5 5 5-5"/><path d="M4 20h16"/></svg>;
    case "chevronDown": return <svg {...common}><path d="m7 9 5 5 5-5"/></svg>;
    case "chevronLeft": return <svg {...common}><path d="m14.5 7-5 5 5 5"/></svg>;
    case "chevronRight": return <svg {...common}><path d="m9.5 7 5 5-5 5"/></svg>;
    case "dots": return <svg {...common}><circle cx="6" cy="12" r="1" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1" fill="currentColor" stroke="none"/><circle cx="18" cy="12" r="1" fill="currentColor" stroke="none"/></svg>;
    case "sparkle": return <svg {...common}><path d="m12 2 1.4 5.1L18 9l-4.6 1.9L12 16l-1.4-5.1L6 9l4.6-1.9L12 2Z"/><path d="m19 15 .7 2.3L22 18l-2.3.7L19 21l-.7-2.3L16 18l2.3-.7L19 15Z"/></svg>;
    case "arrowUp": return <svg {...common}><path d="M12 18V6"/><path d="m7 11 5-5 5 5"/></svg>;
    case "arrowRight": return <svg {...common}><path d="M4 12h16"/><path d="m14 6 6 6-6 6"/></svg>;
    case "target": return <svg {...common}><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r="1.2" fill="currentColor"/></svg>;
    case "link": return <svg {...common}><path d="M9.5 14.5 14.5 9.5"/><path d="M7 17H6a4 4 0 0 1 0-8h3"/><path d="M17 7h1a4 4 0 0 1 0 8h-3"/></svg>;
    case "meta": return <svg {...common}><path d="M4 16c2.3-6.2 4.4-8.9 6.4-8.1 1.5.6 2.1 3.2 3.3 3.2 1.5 0 2.2-3.1 4.3-3.1 1.1 0 1.9.9 2.5 2.6"/></svg>;
  }
}

